            raise ValueError("Unsupported binary operator")
        raise ValueError(f"Unsupported node: {type(node)}")

    try:
        tree = ast.parse(expr, mode='eval')
        return _eval(tree.body)
    except Exception as e:
        print(f"Error: {e}")
        return False

