import ast
import operator
from app.services import users


def handle_filter_users(params: dict) -> tuple[int, dict]:
    expr = params.get("where")
    if not isinstance(expr, str):
        return 400, {"error": "invalid filter"}

    def _eval(node, user):
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            if node.id in user:
                return user[node.id]
            raise ValueError(f"Unknown variable: {node.id}")
        elif isinstance(node, ast.Compare):
            left = _eval(node.left, user)
            for op, comparator in zip(node.ops, node.comparators):
                right = _eval(comparator, user)
                ops = {
                    ast.Eq: operator.eq,
                    ast.NotEq: operator.ne,
                    ast.Lt: operator.lt,
                    ast.LtE: operator.le,
                    ast.Gt: operator.gt,
                    ast.GtE: operator.ge,
                }
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        elif isinstance(node, ast.BoolOp):
            values = [_eval(v, user) for v in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            elif isinstance(node.op, ast.Or):
                return any(values)
        elif isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return not _eval(node.operand, user)
        raise ValueError("Invalid expression")

    try:
        tree = ast.parse(expr, mode='eval')
    except SyntaxError:
        return 400, {"error": "invalid filter"}

    filtered_users = []
    for user in users.get_all_users():
        try:
            if _eval(tree.body, user):
                filtered_users.append(user)
        except Exception:
            return 400, {"error": "invalid filter"}

    return 200, {"users": sorted(filtered_users, key=lambda x: x["id"])}
